    if mode=='dwell_pts':   # points within +-dwell window around checkin
        s=g[(g.rel>=-60)]; s=s if len(s)>=2 else g
    if mode=='last5': s=g.sort_values('seq').tail(5)
    if mode=='post': s=g[g.rel>=0]; s=s if len(s)>=2 else g.tail(3)
