    out[mode]=(d.median(),d.quantile(.75),d.quantile(.9),(d<30).mean())
print(pd.DataFrame(out,index=['median','p75','p90','share<30m']).T.round(1))
print(tr.groupby('visit_id').rel.agg(['min','max']).describe().round(0))
# trail shape for a typical found visit
g=tr[tr.visit_id==VS.visit_id.iloc[3]].sort_values('seq'); print(g[['seq','rel','x','y','accuracy_m']].head(12).to_string()); print(g[['seq','rel','x','y','accuracy_m']].tail(6).to_string()); print('checkin',g.checkin_x.iloc[0],g.checkin_y.iloc[0],'truth',VS.iloc[3][['surveyed_x','surveyed_y']].tolist(),'dwell',g.dwell_s.iloc[0])
